\section{Introduction}

Many empirical procedures summarise a collection of non-negative integer
``demands'' by a threshold that tolerates a prescribed number of exceedances. The
demands might be document lengths, request sizes, latencies or resource
requirements. Given a \emph{gate} $g$, meaning the number of exceedances one is
willing to tolerate, the \emph{knee} is the smallest threshold exceeded by at most
$g$ items. Comparing two collections by their knees at a handful of gates is
common. We call this \emph{knee stability}. It is usually done by recomputing knees
at each gate for each collection, a \emph{sweep}.

This paper studies knee stability exactly. The central observation is elementary
but has strong consequences: \emph{the knee is an order statistic, so agreement of
knees on an interval of gates is exactly agreement of the inverse distribution
function on the corresponding interval of ranks.} We make this precise through a
Galois connection between the knee function and the upper-tail counting function.
We then answer three questions completely:
\begin{enumerate}
\item \textbf{All gates.} When do two collections have the same knee at every gate?
  (Theorem~\ref{thm:main-all}.)
\item \textbf{Gate windows.} When do they have the same knee on a window of gates?
  (Theorems~\ref{thm:window} and~\ref{thm:band}.) We also show that a natural but
  wrong formulation fails (Proposition~\ref{prop:naive}).
\item \textbf{Approximate agreement.} How does closeness of the data control
  closeness of knees? (Theorem~\ref{thm:shift} and its corollaries.)
\end{enumerate}
In every case the answer can be read off a single object, the tail histogram,
with no sweep. Section~\ref{sec:conj} adds the combinatorial picture: knees and
tails are conjugate partitions, and their common area is the total demand.

\subsection*{Notation}
All numbers are natural numbers $\N=\{0,1,2,\dots\}$. A \emph{multiset} $D$ over
$\N$ is a finite unordered collection with repetitions. We write $|D|$ for its
cardinality counted with multiplicity, $\#_D(v)$ for the multiplicity of $v$, $\max
D$ for its largest element (with $\max\varnothing=0$), and $\sum D$ for the sum of
its elements. $D+E$ is the multiset union, which adds multiplicities. For a
predicate $P$, $D|_P$ is the sub-multiset of elements satisfying $P$. In particular
$D|_{>0}$ is the multiset of positive demands. Brackets $[P]$ denote the indicator
of a proposition $P$.

\section{Definitions}

\begin{definition}[Upper-tail counting function]
For a demand multiset $D$ and a threshold $t\in\N$,
\[
\tail_D(t)=\bigl|D|_{>t}\bigr|=\#\{d\in D: d>t\}\quad\text{(with multiplicity)}.
\]
\end{definition}

\begin{definition}[Knee]
For a gate $g\in\N$,
\[
\knee_D(g)=\min\{t\in\N:\tail_D(t)\le g\}.
\]
The set is non-empty because $\tail_D(\max D)=0\le g$ (Lemma~\ref{lem:basic}).
\end{definition}

\begin{definition}[Clamp]
For $a,w,x\in\N$, $\clamp_{a,w}(x)=\min\bigl(\max(x,a),\,a+w\bigr)$, the projection
of $x$ onto the integer interval $[a,a+w]$.
\end{definition}

\begin{definition}[Decreasing arrangement]
$\sortdown(D)=(d_0\ge d_1\ge\dots\ge d_{n-1})$ is the list of elements of $D$ in
non-increasing order, $n=|D|$. For $g\ge n$ we set $d_g:=0$.
\end{definition}

\begin{example}[Running example]
For $D=\{7,5,5,3,1,0\}$:
\begin{center}
\begin{tabular}{lcccccccc}
\toprule
$t$ or $g$ & 0 & 1 & 2 & 3 & 4 & 5 & 6 & 7\\
\midrule
$\tail_D(t)$ & 5 & 4 & 4 & 3 & 3 & 1 & 1 & 0\\
$\knee_D(g)$ & 7 & 5 & 5 & 3 & 1 & 0 & 0 & 0\\
\bottomrule
\end{tabular}
\end{center}
\end{example}

\section{Elementary properties and the Galois connection}

\begin{lemma}[Basic properties of the tail]\label{lem:basic}
\begin{enumerate}
\item If every $d\in D$ satisfies $d\le t$, then $\tail_D(t)=0$; in particular
  $\tail_D(\max D)=0$.
\item $\tail_D$ is antitone: $s\le t\Rightarrow\tail_D(t)\le\tail_D(s)$.
\item $\tail_D(t)\le|D|$.
\item $\tail_{D+E}(t)=\tail_D(t)+\tail_E(t)$, and
  $\tail_{\{a\}+D}(t)=\tail_D(t)+[t<a]$.
\end{enumerate}
\end{lemma}

\begin{proof}[Proof sketch]
(1) The filter $D|_{>t}$ is empty. (2) $s\le t$ gives $D|_{>t}\subseteq D|_{>s}$.
(3) A sub-multiset is no larger than the whole. (4) Filtering commutes with
multiset union, and cardinality is additive.
\end{proof}

\begin{theorem}[Galois connection]\label{thm:galois}
For all $D$, $g$, $t$:\quad $\knee_D(g)\le t\iff\tail_D(t)\le g$.
\end{theorem}

\begin{proof}
By definition of the minimum, $\knee_D(g)\le t$ holds iff some $m\le t$ has
$\tail_D(m)\le g$. If such an $m$ exists, antitonicity gives
$\tail_D(t)\le\tail_D(m)\le g$. Conversely take $m=t$.
\end{proof}

\begin{corollary}\label{cor:galois}
For all $D$, $g$, $t$:
\begin{enumerate}
\item $t<\knee_D(g)\iff g<\tail_D(t)$;
\item $\tail_D(\knee_D(g))\le g$;
\item $\knee_D$ is antitone in $g$;
\item $\knee_D(g)\le\max D$;
\item $\knee_D(g)=0\iff\tail_D(0)\le g$, that is, iff $D$ has at most $g$ positive
  demands.
\end{enumerate}
\end{corollary}

\begin{proof}[Proof sketch]
(1) is the contrapositive of Theorem~\ref{thm:galois}. (2) takes $t=\knee_D(g)$.
For (3), if $g\le h$ then $\tail_D(\knee_D(g))\le g\le h$. (4) uses
Lemma~\ref{lem:basic}(1). (5) takes $t=0$.
\end{proof}

\begin{lemma}[Pointwise criterion]\label{lem:pointwise}
For a fixed gate $g$,
\[
\knee_D(g)=\knee_{D'}(g)\iff\forall t,\ \bigl(\tail_D(t)\le g\iff\tail_{D'}(t)\le g\bigr).
\]
\end{lemma}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:galois} the right-hand side says that the up-sets
$\{t:\knee_D(g)\le t\}$ and $\{t:\knee_{D'}(g)\le t\}$ coincide. Two natural numbers
with the same up-set are equal.
\end{proof}

This lemma is the engine behind all later results. A knee at a single gate depends
on the tail only through the binary classification ``$\le g$'' versus ``$>g$''.

\begin{theorem}[Order statistic]\label{thm:order}
For every $D$ and every $g$, $\knee_D(g)=d_g$, the $g$-th entry (0-indexed) of
$\sortdown(D)$, and $0$ when $g\ge|D|$.
\end{theorem}

\begin{proof}[Proof sketch]
$\tail_D(t)$ equals the number of entries of $\sortdown(D)$ exceeding $t$, since
the list is a permutation of $D$. By induction on a non-increasing list
$L=(x,L')$ one shows $L_g\le t\iff\#\{\text{entries of }L\text{ exceeding }t\}\le g$
(with $L_g:=0$ past the end). For $g=0$: if $x\le t$, every entry of $L'$ is
$\le x\le t$, so the count is $0$; if $x>t$ the count is at least $1$. For $g=g'+1$:
if $x>t$ the count is one plus the count for $L'$, and the induction hypothesis
applies; if $x\le t$ both sides hold, since $L'_{g'}\le x\le t$ or $L'_{g'}=0$.
Hence $d_g$ satisfies the same Galois characterisation as $\knee_D(g)$. Two
quantities with identical up-sets are equal.
\end{proof}

\section{Agreement at all gates}

\begin{theorem}[Knee stability $\iff$ tail exchangeability]\label{thm:knee-tail}
For all demand multisets $D,D'$,
\[
\bigl(\forall g,\ \knee_D(g)=\knee_{D'}(g)\bigr)\iff\bigl(\forall t,\ \tail_D(t)=\tail_{D'}(t)\bigr).
\]
\end{theorem}

\begin{proof}
($\Leftarrow$) Apply Lemma~\ref{lem:pointwise} at each gate. ($\Rightarrow$) Fix
$t$ and let $g=\tail_{D'}(t)$. By Theorem~\ref{thm:galois}, $\knee_{D'}(g)\le t$,
hence $\knee_D(g)\le t$ and so $\tail_D(t)\le\tail_{D'}(t)$. The reverse inequality
follows by symmetry.
\end{proof}

\begin{lemma}[Histogram as discrete derivative]\label{lem:deriv}
For all $k\in\N$, $\tail_D(k)=\tail_D(k+1)+\#_D(k+1)$. Moreover
$\tail_{D|_{>0}}(t)=\tail_D(t)$ for all $t$.
\end{lemma}

\begin{proof}[Proof sketch]
Induct on $D$ using Lemma~\ref{lem:basic}(4). Adding an element $a$ changes both
sides by $[k<a]=[k+1<a]+[a=k+1]$. For the second claim, $d>t\ge0$ already implies
$d>0$.
\end{proof}

\begin{theorem}[Main theorem, all gates]\label{thm:main-all}
For all demand multisets $D,D'$ the following are equivalent:
\begin{enumerate}
\item $\knee_D=\knee_{D'}$ (equal knees at every gate);
\item $\tail_D=\tail_{D'}$ (equal upper-tail counting functions);
\item $D|_{>0}=D'|_{>0}$ (equal multisets of positive demands).
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1)$\iff$(2) is Theorem~\ref{thm:knee-tail}. (2)$\Rightarrow$(3): for each
$v=k+1\ge1$, Lemma~\ref{lem:deriv} gives $\#_D(k+1)=\tail_D(k)-\tail_D(k+1)$, and
the same for $D'$; multiplicities at $0$ are removed by the filter.
(3)$\Rightarrow$(2): $\tail_D=\tail_{D|_{>0}}=\tail_{D'|_{>0}}=\tail_{D'}$.
\end{proof}

\begin{corollary}[Positive demands]
If every element of $D$ and of $D'$ is positive, then $\knee_D=\knee_{D'}\iff D=D'$.
\end{corollary}

\begin{proposition}[The unguarded statement is false]\label{prop:unguarded}
It is not true that $\knee_D=\knee_{D'}$ implies $D=D'$ for all $D,D'$.
\end{proposition}

\begin{proof}
Take $D=\{0\}$ and $D'=\varnothing$. Neither has positive demands, so their knees
agree by Theorem~\ref{thm:main-all}, yet $D\neq D'$. A less trivial instance is
$\{4,2,2\}$ versus $\{0,2,4,0,2\}$.
\end{proof}

\begin{theorem}[Finite sweep]\label{thm:sweep}
Let $m=\max(|D|,|D'|)$. Then
$\knee_D=\knee_{D'}\iff\forall g<m,\ \knee_D(g)=\knee_{D'}(g)$.
\end{theorem}

\begin{proof}[Proof sketch]
For $g\ge m$, $\tail_D(0)\le|D|\le g$, so $\knee_D(g)=0$ by
Corollary~\ref{cor:galois}(5). Likewise $\knee_{D'}(g)=0$.
\end{proof}

\section{Agreement on a window of gates}

Fix a gate window $W=\{g: a\le g<a+w\}$ of width $w$.

\begin{lemma}\label{lem:clamp}
For fixed $t$, put $x=\tail_D(t)$ and $y=\tail_{D'}(t)$. Then
\[
\bigl(\forall g\in W,\ x\le g\iff y\le g\bigr)\iff\clamp_{a,w}(x)=\clamp_{a,w}(y).
\]
\end{lemma}

\begin{proof}[Proof sketch]
Suppose $\clamp(x)<\clamp(y)$. Then $g:=\clamp(x)$ lies in $W$, because $a\le g$
and $g<\clamp(y)\le a+w$. We also have $x\le g<y$, which contradicts the left side.
The other order is symmetric. Conversely, if the clamps agree, then for each $g\in W$
the comparison $x\le g$ is decided by $\clamp(x)$, since $a\le g<a+w$. So it agrees
with $y\le g$.
\end{proof}

\begin{theorem}[Main theorem, gate window]\label{thm:window}
For all $D,D'$ and $a,w\in\N$,
\[
\bigl(\forall g,\ a\le g<a+w\Rightarrow\knee_D(g)=\knee_{D'}(g)\bigr)
\iff
\bigl(\forall t,\ \clamp_{a,w}(\tail_D(t))=\clamp_{a,w}(\tail_{D'}(t))\bigr).
\]
\end{theorem}

\begin{proof}
Apply Lemma~\ref{lem:pointwise} at each $g\in W$. Exchange the quantifiers over
$g$ and $t$, then apply Lemma~\ref{lem:clamp} at each $t$.
\end{proof}

In the language of distribution functions, agreement of the generalised inverse
of $\tail_D$ on the rank interval $[a,a+w)$ is agreement of $\tail_D$ itself after
projection onto the \emph{count band} $[a,a+w]$. This band is one unit wider than
the gate window.

\begin{theorem}[Band formulation]\label{thm:band}
Assume $w>0$. The window condition of Theorem~\ref{thm:window} holds iff for every
threshold $t$:
\begin{enumerate}
\item $\tail_D(t)\le a\iff\tail_{D'}(t)\le a$;
\item $a+w\le\tail_D(t)\iff a+w\le\tail_{D'}(t)$;
\item if $a<\tail_D(t)<a+w$ then $\tail_D(t)=\tail_{D'}(t)$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
For $x=\tail_D(t)$, the three cases $x\le a$, $a<x<a+w$ and $x\ge a+w$ give
$\clamp(x)=a$, $x$ and $a+w$ respectively. These values are pairwise distinct when
$w>0$, so equality of clamps is exactly conditions (1)--(3). Each direction is a
short case analysis in linear arithmetic.
\end{proof}

\begin{example}
Let $D=\{9,6,4,2\}$ and $D'=\{8,6,4,1,1\}$, with knee profiles
$(9,6,4,2,0,\dots)$ and $(8,6,4,1,1,0,\dots)$. They agree exactly on the window
$\{1,2\}$, so $a=1$ and $w=2$. Their tails at $t=0,\dots,9$ are
$(4,4,3,3,2,2,1,1,1,0)$ and $(5,3,3,3,2,2,1,1,0,0)$. They differ at $t=0,1,8$, but
clamping to $[1,3]$ gives $(3,3,3,3,2,2,1,1,1,1)$ for both.
\end{example}

\begin{proposition}[The naive closed-band formulation is false]\label{prop:naive}
The following statement fails in general: for all $D,D'$ and $a,b$,
\[
\bigl(\forall g\in[a,b],\ \knee_D(g)=\knee_{D'}(g)\bigr)\iff
\bigl(\forall t,\ a\le\tail_D(t)\le b\Rightarrow\tail_D(t)=\tail_{D'}(t)\bigr).
\]
\end{proposition}

\begin{proof}
Take $D=\{3\}$, $D'=\{2\}$, $a=b=1$. Both knees at gate $1$ equal $0$, since each
multiset has only one positive demand. At $t=2$, however, $\tail_D(2)=1\in[1,1]$
while $\tail_{D'}(2)=0$.
\end{proof}

The counterexample shows where the clamp is needed. On the boundary of the band,
the tails need only fall on the same side, not coincide.

\section{Conjugate-partition duality and the area identity}\label{sec:conj}

Draw $D$ as a Ferrers diagram whose rows, longest first, have lengths
$d_0\ge d_1\ge\cdots$. By Theorem~\ref{thm:order} the row lengths are the knees. The
column heights are the tails.

\begin{theorem}[Conjugate duality]\label{thm:conj}
For all $D$, $t$, $g$:
\[
\tail_D(t)=\#\{g<|D|: t<\knee_D(g)\},\qquad
\knee_D(g)=\#\{t<\max D: g<\tail_D(t)\}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Corollary~\ref{cor:galois}(1), $t<\knee_D(g)\iff g<\tail_D(t)$. So the first set
is $\{0,\dots,\tail_D(t)-1\}$, using $\tail_D(t)\le|D|$. The second set is
$\{0,\dots,\knee_D(g)-1\}$, using $\knee_D(g)\le\max D$.
\end{proof}

\begin{theorem}[Area identity]\label{thm:area}
$\displaystyle\sum_{g=0}^{|D|-1}\knee_D(g)=\sum_{d\in D}d.$
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:order} the left side is the sum of the list $\sortdown(D)$,
which is $\sum D$. Counting boxes by columns gives the dual identity
$\sum_{t<\max D}\tail_D(t)=\sum D$.
\end{proof}

\section{Quantitative stability}

\begin{theorem}[Gate shift $\iff$ uniform tail bound]\label{thm:shift}
For all $D,D'$ and $k\in\N$:
\[
\bigl(\forall g,\ \knee_{D'}(g+k)\le\knee_D(g)\bigr)\iff\bigl(\forall t,\ \tail_{D'}(t)\le\tail_D(t)+k\bigr).
\]
\end{theorem}

\begin{proof}
($\Rightarrow$) Fix $t$ and set $g=\tail_D(t)$. Then $\knee_D(g)\le t$, so
$\knee_{D'}(g+k)\le t$, so $\tail_{D'}(t)\le g+k$, using Theorem~\ref{thm:galois}
twice. ($\Leftarrow$) Fix $g$. It suffices to show $\tail_{D'}(\knee_D(g))\le g+k$.
The hypothesis gives $\tail_{D'}(\knee_D(g))\le\tail_D(\knee_D(g))+k$, and
Corollary~\ref{cor:galois}(2) gives $\tail_D(\knee_D(g))\le g$.
\end{proof}

\begin{corollary}[Lipschitz sandwich]\label{cor:sandwich}
If $|\tail_D(t)-\tail_{D'}(t)|\le k$ for all $t$, then for every gate $g$,
$\knee_{D'}(g+k)\le\knee_D(g)$ and $\knee_D(g+k)\le\knee_{D'}(g)$.
\end{corollary}

\begin{corollary}[Contamination]\label{cor:contam}
For all $D,E$ and $g$:\quad $\knee_D(g)\le\knee_{D+E}(g)$ and
$\knee_{D+E}(g+|E|)\le\knee_D(g)$.
\end{corollary}

\begin{proof}[Proof sketch]
$\tail_D\le\tail_{D+E}=\tail_D+\tail_E\le\tail_D+|E|$. Apply
Theorem~\ref{thm:shift} with $k=0$ (with the roles of $D$ and $D+E$ swapped) and
with $k=|E|$.
\end{proof}

\begin{corollary}[Merge bounds]
For all $D,E$ and gates $g,h$:
\[
\max\bigl(\knee_D(g),\knee_E(g)\bigr)\le\knee_{D+E}(g),\qquad
\knee_{D+E}(g+h)\le\max\bigl(\knee_D(g),\knee_E(h)\bigr).
\]
\end{corollary}

\begin{proof}[Proof sketch]
The first is Corollary~\ref{cor:contam} applied to $D$ and to $E$. For the second,
put $m=\max(\knee_D(g),\knee_E(h))$. Antitonicity and
Corollary~\ref{cor:galois}(2) give $\tail_{D+E}(m)=\tail_D(m)+\tail_E(m)\le g+h$.
Then apply Theorem~\ref{thm:galois}.
\end{proof}

\section{Algorithms}

Let $n=|D|$ and let $V$ be the number of distinct values.

\begin{algorithm}[Tail histogram]
One pass builds $h(v)=\#_D(v)$. Sorting distinct values decreasingly and
accumulating suffix sums yields $\tail_D$ as $V$ breakpoints, in time
$O(n+V\log V)$ and space $O(V)$. Histograms of shards combine by addition
(Lemma~\ref{lem:basic}(4)).
\end{algorithm}

\begin{algorithm}[Knee from histogram]
By Theorem~\ref{thm:galois}, $\knee_D(g)$ is the least breakpoint $t$ with
$\tail_D(t)\le g$. Binary search costs $O(\log V)$ per gate. Equivalently, by
Theorem~\ref{thm:order}, it is the $g$-th largest element.
\end{algorithm}

\begin{algorithm}[All-gate equality test]
By Theorem~\ref{thm:main-all}, compare the positive parts of the histograms, in
$O(V+V')$. No sweep is needed. A direct sweep would need at most $\max(|D|,|D'|)$
gates (Theorem~\ref{thm:sweep}).
\end{algorithm}

\begin{algorithm}[Window equality test]
By Theorem~\ref{thm:window}, merge the breakpoints of both tails. On each piece,
both tails are constant. Compare their clamps to $[a,a+w]$. Cost $O(V+V')$ for
any window.
\end{algorithm}

\begin{algorithm}[Gate-shift distance]
Compute $k^\ast=\max_t|\tail_D(t)-\tail_{D'}(t)|$ over merged breakpoints. By
Corollary~\ref{cor:sandwich}, each knee profile dominates the other after a shift
of $k^\ast$ gates. By the forward direction of Theorem~\ref{thm:shift}, no smaller
mutual shift exists.
\end{algorithm}

\section{Applications and discussion}

\paragraph{From sweeps to histograms.} By Theorems~\ref{thm:main-all}
and~\ref{thm:window}, the outcome of any knee sweep, at all gates or on any window,
is determined by the tail histograms alone. A sweep over $G$ gates for $C$ cells
costs $G\cdot C$ knee computations. The histogram approach costs one pass per
collection and $O(V)$ per comparison afterwards.

\paragraph{Robustness.} Theorem~\ref{thm:shift} is an equivalence, so the supremum
gap between tails is the right measure of knee discrepancy.
Corollary~\ref{cor:contam} gives a deterministic certificate: $|E|$ spurious items
move knees by at most $|E|$ gates, and only upward.

\paragraph{Zero demands and boundaries.} Proposition~\ref{prop:unguarded} shows
that knees are blind to zero demands. Proposition~\ref{prop:naive} shows that gate
windows $[a,a+w)$ correspond to count bands $[a,a+w]$, with only one bit of
information per threshold on the band boundary.

\paragraph{Relation to classical notions.} Theorem~\ref{thm:galois} is the discrete
duality between a survival function and its quantile function.
Theorem~\ref{thm:conj} is the conjugation of integer partitions, and
Theorem~\ref{thm:area} says a partition and its conjugate have the same size. The
contribution here is the exact window theorem, with its band offset, and the sharp
shift--bound equivalence.

\section{Future work}

\begin{enumerate}
\item \textbf{Gate-shift metric as a Kolmogorov distance.} The least mutual gate
  shift equals $\sup_t|\tail_D(t)-\tail_{D'}(t)|$, as noted in the gate-shift
  distance algorithm. The next step is to develop this as a metric in its own right:
  the $\ell^\infty$ distance between conjugate partitions, an unnormalised
  L\'evy--Kolmogorov distance, with its triangle inequality, normalisation by $|D|$,
  and interaction with pooling.
\item \textbf{Weighted and fractional gates.} For real-weighted demands, the knee at
  a real gate $\gamma$ should be the generalised inverse of the weighted tail, and
  window agreement should be equivalent to agreement of clamped weighted tails. Only
  the Galois connection was used, and it holds for any right-continuous antitone
  tail.
\item \textbf{Sampling stability.} If a subsample of size $n$ has empirical tail
  within $\varepsilon n$ of the scaled population tail (a
  Dvoretzky--Kiefer--Wolfowitz-type event), every sampled knee should lie between
  the population knees at gates $g\pm\varepsilon n$, by
  Corollary~\ref{cor:sandwich}.
\item \textbf{Pooling via conjugate addition.} Tails add under pooling, so the knee
  profile of $D+E$ is the conjugate of the sum of conjugates, and all-gate agreement
  is preserved under pooling with a common collection $E$. Window agreement is
  \emph{not} preserved in general: $\varnothing$ and $\{1\}$ have equal knees ($0$)
  at gate $1$, but after pooling each with $E=\{1\}$ the knees at gate $1$ are $0$
  and $1$. The open problem is to find how the window must move or shrink under
  pooling, which would let windowed profiles be assembled from shard histograms.
\end{enumerate}

\section{Conclusion}

The knee of a demand multiset at a gate is an order statistic, and it is linked to
the upper-tail counting function by a Galois connection. All the results here
follow from that one fact. Equal knees at all gates is the same as equal tails,
which is the same as equal positive data. Equal knees on a gate window is the same
as equal tails clamped to a count band one unit wider. Closeness of tails in sup
norm is the same as closeness of knees up to a gate shift. Each statement is an
exact equivalence, and each comes with a counterexample showing where a looser
version fails. As a result, any question about knees can be answered from a single
tail histogram per collection.

