algorithms.code:
from collections import Counter
from typing import Dict, Iterable


def tail(D: Iterable[int], t: int) -> int:
    return sum(1 for d in D if d > t)


def clamp_band(a: int, w: int, x: int) -> int:
    return min(max(x, a), a + w)


def all_gates_equal(h1: Dict[int, int], h2: Dict[int, int]) -> bool:
    """Equal knees at every gate <=> equal multisets of positive demands."""
    p1 = {v: c for v, c in h1.items() if v > 0 and c > 0}
    p2 = {v: c for v, c in h2.items() if v > 0 and c > 0}
    return p1 == p2


def window_equal(h1: Dict[int, int], h2: Dict[int, int], a: int, w: int) -> bool:
    """Equal knees on gates a <= g < a+w <=> clamp_[a,a+w] tails agree at every t.
    Both tails are constant between consecutive breakpoints, so it suffices to
    test t in {0} U {distinct values}.  Cost O(V1 + V2) after sorting."""
    points = sorted({0} | set(h1) | set(h2))
    def tl(h: Dict[int, int], t: int) -> int:
        return sum(c for v, c in h.items() if v > t)
    return all(clamp_band(a, w, tl(h1, t)) == clamp_band(a, w, tl(h2, t)) for t in points)


def gate_shift_distance(h1: Dict[int, int], h2: Dict[int, int]) -> int:
    """k* = max_t |tail1(t) - tail2(t)|: the least k such that each knee profile,
    shifted by k gates, lies below the other (gate-shift theorem)."""
    points = sorted({0} | set(h1) | set(h2))
    def tl(h: Dict[int, int], t: int) -> int:
        return sum(c for v, c in h.items() if v > t)
    return max(abs(tl(h1, t) - tl(h2, t)) for t in points)


if __name__ == "__main__":
    D, E = Counter([9, 6, 4, 2]), Counter([8, 6, 4, 1, 1])
    print(window_equal(D, E, 1, 2))     # True  (gates 1, 2)
    print(window_equal(D, E, 0, 1))     # False (gate 0: 9 vs 8)
    print(all_gates_equal(Counter([4, 2, 2]), Counter([0, 2, 4, 0, 2])))  # True
    print(gate_shift_distance(D, E))    # 1
